        $albumIds=array_values(array_unique(array_column($tracks,'album_id')));$totals=$repo->counts($albumIds);$counts=[];$generated=[];foreach($repo->albums($albumIds)as $album){$selected=count(array_filter($tracks,fn($row)=>$row['album_id']===$album['id']));if($selected===($totals[$album['id']]??0)){$counts[]=['table'=>'tracks','column'=>'album_id','id'=>$album['id'],'count'=>$selected];$ops[]=['table'=>'albums','id'=>$album['id'],'before'=>['id'=>$album['id'],'rev'=>$album['rev'],'deleted'=>0],'after'=>['id'=>$album['id'],'rev'=>$album['rev'],'deleted'=>1]];}elseif($album['art_source']==='generated')$generated[]=$album['id'];}
