    }
    $raw=metadata_json_body();$mutation=$album||$merging?metadata_album_mutation($db,$raw,$album?$albumMatch[1]:null):null;$input=metadata_input($mutation['input']??$raw);$plan=metadata_plan($input,new MetadataRepositoryNative($db),$auth);if($mutation){$plan['write']['counts']=[...$plan['write']['counts'],...$mutation['counts']];if($mutation['summary'])$plan['write']['summary']=$mutation['summary'];}$impact=array_intersect_key($plan,array_flip(['updated','albumsUpdated','published','madePrivate']));
    if($input['dryRun']){if(strlen(json_encode($plan['preview'],JSON_THROW_ON_ERROR))>8*1024**2)fail('too_large','Preview fewer tracks at once.',413);reply(['dryRun'=>true,'changeId'=>null,...$impact,'preview'=>$plan['preview'],'albumRevs'=>$plan['albumRevs']]);}
    reply([...journal_write($db,$auth,$plan['write']),...$impact,'albumIds'=>$plan['albumIds'],'generatedAlbumIds'=>$plan['generatedAlbumIds']]);
}
